import React, { Component } from 'react';
import ToolIcon from 'Editor/Util/ToolIcon/ToolIcon';

import './_rightclickmenu.scss';

class RightClickMenu extends Component {
  constructor (props) {
    super(props);

    this.menuRef = React.createRef();
  }

  componentDidMount () {
    document.addEventListener('mousedown', this.handleGlobalClick, true);
    document.addEventListener('keydown', this.handleKeyDown, true);
    document.addEventListener('scroll', this.props.onClose, true);
    window.addEventListener('blur', this.props.onClose);
  }

  componentWillUnmount () {
    document.removeEventListener('mousedown', this.handleGlobalClick, true);
    document.removeEventListener('keydown', this.handleKeyDown, true);
    document.removeEventListener('scroll', this.props.onClose, true);
    window.removeEventListener('blur', this.props.onClose);
  }

  handleGlobalClick = (e) => {
    if (this.menuRef.current && !this.menuRef.current.contains(e.target)) {
      this.props.onClose();
    }
  }

  handleKeyDown = (e) => {
    if (e.key === 'Escape') {
      this.props.onClose();
    }
  }

  renderItem = (actionKey) => {
    const action = this.props.actions[actionKey];
    if (!action) return null;

    return (
      <div
        key={actionKey}
        role="menuitem"
        className="right-click-menu-item"
        onClick={(e) => {
          e.stopPropagation();
          action.action();
          this.props.onClose();
        }}>
        <ToolIcon className="right-click-menu-item-icon" name={action.icon} />
        <span className="right-click-menu-item-label">{action.tooltip}</span>
      </div>
    );
  }

  renderDivider = (index) => {
    return <div key={`right-click-menu-divider-${index}`} className="right-click-menu-divider" role="separator" />;
  }

  actionGroups = () => {
    if (this.props.mode === 'paste') {
      return [['paste']];
    }

    let groups = [
      ['copy', 'paste', 'delete'],
      ['flipHorizontal', 'flipVertical'],
      ['sendToFront', 'sendToBack', 'sendBackward', 'sendForward'],
    ];

    if (this.props.showGroupActions) {
      groups.push(['groupIntoClip']);
    }

    if (this.props.showBreakApartActions) {
      groups.push(['breakApartClip']);
    }

    if (this.props.showBooleanActions) {
      groups.push(['booleanUnite', 'booleanSubtract', 'booleanIntersect']);
    }

    return groups;
  }

  getMenuPosition = () => {
    const MENU_WIDTH = 210;
    const MENU_ITEM_HEIGHT = 33;
    const MENU_DIVIDER_HEIGHT = 13;
    const MENU_PADDING = 12;
    const EDGE_MARGIN = 8;

    const groups = this.actionGroups();
    let itemCount = 0;
    let dividerCount = groups.length - 1;
    groups.forEach(group => { itemCount += group.length; });

    const menuHeight = MENU_PADDING + (itemCount * MENU_ITEM_HEIGHT) + (dividerCount * MENU_DIVIDER_HEIGHT);

    let left = this.props.x;
    let top = this.props.y;

    if (left + MENU_WIDTH + EDGE_MARGIN > window.innerWidth) {
      left = window.innerWidth - MENU_WIDTH - EDGE_MARGIN;
    }
    if (top + menuHeight + EDGE_MARGIN > window.innerHeight) {
      top = window.innerHeight - menuHeight - EDGE_MARGIN;
    }

    return { left: Math.max(EDGE_MARGIN, left), top: Math.max(EDGE_MARGIN, top) };
  }

  render() {
    const { left, top } = this.getMenuPosition();

    return (
      <div
        ref={this.menuRef}
        role="menu"
        className="right-click-menu"
        style={{ top, left }}>
        {this.actionGroups().map((group, index) => {
          return (
            <div key={`group-${index}`}>
              {index > 0 && this.renderDivider(index)}
              {group.map(actionKey => this.renderItem(actionKey))}
            </div>
          );
        })}
      </div>
    );
  }
}

export default RightClickMenu;